const body = $json.body || $json;

const value =
  body.entry?.[0]?.changes?.[0]?.value ||
  body.changes?.[0]?.value ||
  body.value ||
  body;

// تجاهل statuses
if (value.statuses?.length) {
  return [];
}

// لازم تكون رسالة
const message = value.messages?.[0];
if (!message) {
  return [];
}

const contact = value.contacts?.[0] || {};

const messageId = message.id || "";
const phone = message.from || contact.wa_id || "";
const clientName = contact.profile?.name || "";
const messageType = message.type || "";

let messageText = "";
let interactiveId = "";

if (messageType === "text") {
  messageText = message.text?.body || "";
} else if (messageType === "button") {
  messageText = message.button?.text || message.button?.payload || "";
  interactiveId = message.button?.payload || "";
} else if (messageType === "interactive") {
  interactiveId =
    message.interactive?.button_reply?.id ||
    message.interactive?.list_reply?.id ||
    "";
  messageText =
    message.interactive?.button_reply?.title ||
    message.interactive?.list_reply?.title ||
    interactiveId ||
    "";
} else {
  return [];
}

messageText = String(messageText).trim();

if (!phone || !messageText) {
  return [];
}

const normalizedText = messageText
  .toLowerCase()
  .replace(/\s+/g, " ")
  .trim();

const greetings = [
  "السلام عليكم","سلام عليكم","مرحبا","هلا","اهلا","أهلا",
  "صباح الخير","مساء الخير","hi","hello","hey"
];

const shortAcknowledgements = [
  "شكرا","شكراً","تمام","نعم","لا","اوكي","أوكي","ok","👍","👌"
];

const isGreetingOnly = greetings.includes(normalizedText);
const isShortAcknowledgement = shortAcknowledgements.includes(normalizedText);

let selectedMenuOption = "";
if (["1", "١"].includes(normalizedText)) selectedMenuOption = "1";
if (["2", "٢"].includes(normalizedText)) selectedMenuOption = "2";
if (["3", "٣"].includes(normalizedText)) selectedMenuOption = "3";
if (["4", "٤"].includes(normalizedText)) selectedMenuOption = "4";

let detectedService = "";
if (selectedMenuOption === "1") detectedService = "Company Formation";
if (selectedMenuOption === "2") detectedService = "HR Solutions";
if (selectedMenuOption === "3") detectedService = "Government Relations";
if (selectedMenuOption === "4") detectedService = "Premium Residency";

return [
  {
    json: {
      message_id: messageId,
      phone,
      client_name: clientName,
      message_text: messageText,
      normalized_text: normalizedText,
      interactive_id: interactiveId,
      message_type: messageType,
      conversation_id: `wa_${phone}`,
      is_greeting_only: isGreetingOnly,
      is_short_acknowledgement: isShortAcknowledgement,
      selected_menu_option: selectedMenuOption,
      detected_service: detectedService,
      source_workflow: "WhatsApp Workflow",
      received_at: new Date().toISOString()
    }
  }
];

// Pick Latest CRM Lead
// Use after "Search CRM by WhatsApp Phone"
// Purpose: avoid using an old duplicate CRM page for the same WhatsApp number

function normalizePhone(v) {
  return String(v || "")
    .replace(/[^\d]/g, "")
    .replace(/^00/, "")
    .replace(/^0/, "966");
}

function safeString(v) {
  if (v === undefined || v === null) return "";
  if (Array.isArray(v)) return v.join(", ");
  if (typeof v === "object") return JSON.stringify(v);
  return String(v);
}

const inputItems = $input.all();

let normalizedInput = {};
try {
  normalizedInput = $("Normalize WhatsApp Input").first().json || {};
} catch (e) {
  normalizedInput = {};
}

const incomingPhone = normalizePhone(
  normalizedInput.phone ||
  normalizedInput.from ||
  normalizedInput.whatsapp ||
  ""
);

const candidates = inputItems
  .map((item) => item.json || {})
  .filter((row) => {
    const rowPhone = normalizePhone(
      row.property_whats_app ||
      row.property_whatsapp ||
      row.property_whatsapp_phone ||
      row.property_whats_app_phone ||
      row["WhatsApp"] ||
      row["WhatsApp Phone"] ||
      ""
    );

    if (!incomingPhone) return true;
    return rowPhone === incomingPhone || rowPhone.endsWith(incomingPhone.slice(-9));
  });

if (!candidates.length) {
  return [
    {
      json: {
        crm_exists: false,
        crm_page_id: "",
        crm_url: "",
        pick_crm_error: "No matching CRM lead found",
        incoming_phone: incomingPhone,
        source_node: "Pick Latest CRM Lead"
      }
    }
  ];
}

// Prefer the newest / most recently edited item
candidates.sort((a, b) => {
  const aTime = new Date(
    a.last_edited_time ||
    a.created_time ||
    a.property_last_whatsapp_message_date ||
    a.property_last_reply_date ||
    0
  ).getTime();

  const bTime = new Date(
    b.last_edited_time ||
    b.created_time ||
    b.property_last_whatsapp_message_date ||
    b.property_last_reply_date ||
    0
  ).getTime();

  return bTime - aTime;
});

const crm = candidates[0];

return [
  {
    json: {
      ...crm,

      crm_exists: true,
      crm_page_id: safeString(crm.id),
      crm_url: safeString(crm.url),
      crm_name: safeString(crm.name),

      selected_crm_source: "latest_matching_phone",
      matching_records_count: candidates.length,
      incoming_phone: incomingPhone,
      source_node: "Pick Latest CRM Lead"
    }
  }
];

// Stable Prepare AI Context - No Stop Version
// هذا الكود لا يوقف الفلو حتى لو Normalize node غير متاح

const crm = $json || {};

let wa = {};

// نقرأ رسالة الواتساب من Normalize بطريقة آمنة
try {
  const normalizeItems = $items("Normalize WhatsApp Input");
  if (normalizeItems && normalizeItems.length > 0) {
    wa = normalizeItems[0].json || {};
  }
} catch (e) {
  wa = {};
}

function safe(value, fallback = "") {
  if (value === undefined || value === null) return fallback;
  if (Array.isArray(value)) {
    if (value.length === 0) return fallback;
    return value[0];
  }
  return value;
}

function safeString(value, fallback = "") {
  const v = safe(value, fallback);
  if (v === undefined || v === null) return fallback;
  return String(v).trim();
}

function cleanValue(value, fallback = "") {
  const v = safeString(value, fallback);
  if (!v) return fallback;
  if (v === "[null]") return fallback;
  if (v === "undefined") return fallback;
  if (v === "null") return fallback;
  return v;
}

function normalizeNumber(text) {
  const map = {
    "٠": "0",
    "١": "1",
    "٢": "2",
    "٣": "3",
    "٤": "4",
    "٥": "5",
    "٦": "6",
    "٧": "7",
    "٨": "8",
    "٩": "9"
  };

  return String(text || "")
    .replace(/[٠-٩]/g, d => map[d] || d)
    .trim();
}

// الرسالة الحالية
const messageText = safeString(
  wa.message_text ||
  wa.normalized_text ||
  crm.message_text ||
  crm.normalized_text ||
  crm.property_last_whats_app_message ||
  ""
);

const normalizedText = normalizeNumber(messageText);

const isNumericReply = /^[0-9]+$/.test(normalizedText);
const numericChoice = isNumericReply ? Number(normalizedText) : null;

// رقم العميل
const phone = safeString(
  wa.phone ||
  crm.phone ||
  crm.property_whats_app ||
  crm.property_whatsapp ||
  crm.property_whats_app_phone ||
  crm.property_whatsapp_phone ||
  ""
);

// اسم العميل
const clientName = safeString(
  wa.client_name ||
  crm.client_name ||
  crm.name ||
  "WhatsApp Client"
);

// حالة العميل من Notion
const advisorStep = cleanValue(
  crm.property_advisor_step ||
  crm.advisor_step ||
  crm["Advisor Step"],
  "Main Menu"
);

const whatsappStage = cleanValue(
  crm.property_whats_app_stage ||
  crm.property_whatsapp_stage ||
  crm.whatsapp_stage ||
  crm["WhatsApp Stage"],
  "New Inquiry"
);

const selectedServicePath = cleanValue(
  crm.property_selected_service_path ||
  crm.selected_service_path ||
  crm["Selected Service Path"],
  ""
);

return [
  {
    json: {
      ...crm,

      crm_page_id: safeString(crm.id || crm.crm_page_id),
      crm_url: safeString(crm.url || crm.crm_url),

      client_name: clientName,
      phone,

      message_id: safeString(wa.message_id || crm.message_id),
      message_text: messageText,
      normalized_text: normalizedText,
      message_type: safeString(wa.message_type || crm.message_type || "text"),
      conversation_id: safeString(wa.conversation_id || crm.conversation_id || `wa_${phone}`),

      current_agent: cleanValue(
        crm.property_current_whats_app_agent ||
        crm.current_agent ||
        crm["Current WhatsApp Agent"],
        "Mazen"
      ),

      whatsapp_stage: whatsappStage,
      advisor_step: advisorStep,
      selected_service_path: selectedServicePath,

      investor_profile_type: cleanValue(
        crm.property_investor_profile_type ||
        crm.investor_profile_type,
        "Not Sure"
      ),

      investor_nationality_category: cleanValue(
        crm.property_investor_nationality_category ||
        crm.investor_nationality_category,
        "Not Sure"
      ),

      investment_sector: cleanValue(
        crm.property_investment_sector ||
        crm.investment_sector,
        "Not Sure"
      ),

      investment_subsector: cleanValue(
        crm.property_investment_subsector ||
        crm.investment_subsector,
        "Not Sure"
      ),

      special_activity_flags: cleanValue(
        crm.property_special_activity_flags ||
        crm.special_activity_flags,
        "None"
      ),

      investment_procedure_requested: cleanValue(
        crm.property_investment_procedure_requested ||
        crm.investment_procedure_requested,
        "Not Sure"
      ),

      recommended_legal_entity: cleanValue(
        crm.property_recommended_legal_entity ||
        crm.recommended_legal_entity,
        "Not Sure"
      ),

      partners_count: cleanValue(
        crm.property_partners_count ||
        crm.partners_count,
        "Not Defined"
      ),

      is_numeric_reply: isNumericReply,
      numeric_choice: numericChoice,

      selected_menu_option: safeString(wa.selected_menu_option || crm.selected_menu_option || ""),
      detected_service: safeString(wa.detected_service || crm.detected_service || selectedServicePath || ""),

      is_greeting_only: wa.is_greeting_only === true || crm.is_greeting_only === true,
      is_short_acknowledgement: wa.is_short_acknowledgement === true || crm.is_short_acknowledgement === true,

      user_intent: isNumericReply ? "menu_selection" : "general",

      route_to_ai: false,
      send_to_menu_router: true,

      debug_prepare_context: {
        node: "Prepare AI Context",
        normalize_found: Object.keys(wa).length > 0,
        message_text: messageText,
        normalized_text: normalizedText,
        phone,
        advisor_step: advisorStep,
        whatsapp_stage: whatsappStage,
        selected_service_path: selectedServicePath
      }
    }
  }
];

// Unified routing. Skip the AI on menu navigation, booking, onboarding, and job-seekers.
const item = items[0].json || {};
const msg = String(item.message_text || item.normalized_text || item.property_last_whats_app_message || item.property_last_whatsapp_message || '').trim();
const advisorStep = String(item.investment_advisor_summary || item.property_investment_advisor_summary || item.advisor_step || item.property_advisor_step || 'Main Menu').trim();
const humanRequired = item.human_required === true || item.property_human_required === true;
const aiEnabled = item.ai_enabled !== false && item.property_ai_enabled !== false;

let norm = {};
try { norm = $('Normalize WhatsApp Input').first().json || {}; } catch (e) {}
const isGreeting = norm.is_greeting_only === true;
const nid = String(norm.interactive_id || '').trim();
const hasEmail = String(item.property_email || '').trim() !== '';
const isOnboarding = !hasEmail;

const wantsMenu = /خدمات|قائمة|menu/i.test(msg) || /^(الباقات|باقات|الباقة|الرئيسية|الحلول|حلول)$/.test(msg);
// أبواب الموقع الجديد وصفّا الطلبات والدفع تردّ من القائمة مباشرة؛
// إجابة العميل بعدها نص حرّ فتذهب للوكيل الذكي ويكمل رحلة النطاق والعرض.
const isJourneyTap = nid === 'start_consulting' || nid === 'start_government' ||
  nid === 'start_formation' || nid === 'my_orders' || nid === 'pay_now';
const isMenuNav = nid === 'more' || nid === 'packages' || nid === 'ai_consult' ||
  nid === 'main_menu' || nid === 'back_main' || nid === 'jobseeker' || nid === 'solutions' ||
  isJourneyTap ||
  /^cat_/.test(nid) || /^catall_/.test(nid) || /^svc_/.test(nid) ||
  /^pkg_/.test(nid) || /^pkggrp_/.test(nid) || /^sol_/.test(nid);
const isBooking = nid === 'consult' || nid === 'booking' || /^bkday_/.test(nid) || /^bktime_/.test(nid);
const isHumanTap = nid === 'human_service' || /مستشارك البشري|مستشار بشري/.test(msg);
const menuMoment = isGreeting || wantsMenu || isMenuNav || isBooking || isOnboarding;

let route_to_menu = false, route_to_ai = false, route_to_advisor = false, route_to_human = false, router_reason = '';
if (humanRequired || !aiEnabled) { route_to_human = true; router_reason = 'human_required_or_ai_disabled'; }
else if (isHumanTap) { router_reason = 'human_handoff_link'; }
else if (isOnboarding) { router_reason = 'onboarding'; }
else if (isBooking) { router_reason = 'booking_flow'; }
else if (menuMoment) { router_reason = 'interactive_menu_only'; }
else { route_to_ai = true; router_reason = 'unified_smart_agent'; }

return [{ json: { ...item, message_text: msg, advisor_step: advisorStep, whatsapp_stage: item.whatsapp_stage || item.property_whats_app_stage || '', selected_service_path: item.selected_service_path || item.property_selected_service_path || '', route_to_menu, route_to_ai, route_to_advisor, route_to_human, reset_to_menu: false, send_to_menu_router: false, router_reason } }];

// Conversation Start Check — client alerts only
const j = $json;
const phone = String(j.phone || '');
const ownerNumbers = ['966503793356', '966530540231'];
const isOwner = ownerNumbers.includes(phone);

let crmExists = false;
let lastEdited = 0;
try {
  const p = $('Pick Latest CRM Lead').first().json;
  crmExists = p.crm_exists === true;
  lastEdited = new Date(p.last_edited_time || p.created_time || 0).getTime();
} catch (e) {}

const hoursSince = lastEdited ? (Date.now() - lastEdited) / 3600000 : 9999;
const isNew = !crmExists;
const isReturning = crmExists && hoursSince >= 6;
const startType = isNew ? 'عميل جديد 🎉' : 'عميل عائد 🔄';

return [{
  json: {
    is_conversation_start: !isOwner && (isNew || isReturning),
    is_owner_test: isOwner,
    start_type: startType,
    client_name: j.client_name || 'عميل واتساب',
    phone,
    message_text: j.message_text || '',
    crm_url: j.crm_url || '',
    crm_page_id: j.crm_page_id || '',
    monitor_url: 'https://app.notion.com/p/0b126b52ef9c40b5821f3495ae2985b4'
  }
}];

const j=$input.first().json;
const phone=((j.phone||'')+'').trim();
const msg=((j.message_text||'')+'').trim();
const m=msg.match(/\bBP-[A-Z0-9]{6}\b/i);
// رمز دخول الخدمات المشتركة فقط إذا أرسل العميل الرمز وحده (أو معه كلمة/كلمتين).
// رقم الطلب القادم من مركز عمليات العميل يشبه الرمز شكلاً وليس رمز دخول: كان
// الوكيل يبحث عنه في نوشن ولا يجده فيرد «الرمز غير صحيح» على عميل يسأل عن طلبه.
const rest=m?msg.replace(m[0],'').replace(/\s+/g,' ').trim():'';
const fromPortal=/مركز عمليات العميل|Client Operations Center|طلبي|طلباتي|الطلب رقم|بخصوص الطلب|تذكرة|order|ticket/i.test(msg);
const codeFound=(m&&!fromPortal&&rest.length<=25)?m[0].toUpperCase():'';
return [{json:Object.assign({},j,{ss_phone:phone,ss_code:codeFound,ss_order_ref:(m&&!codeFound)?m[0].toUpperCase():'',qPhone:JSON.stringify({filter:{property:'WhatsAppPhone',rich_text:{equals:phone||'NONE'}}}),qCode:JSON.stringify({filter:{property:'الرمز',rich_text:{equals:codeFound||'NONE'}}})})}];

// ===== Build Menu Response (bilingual AR/EN) — يقرأ الكتالوج الحي من الموقع =====
// القائمة كانت تحمل الأقسام والخدمات والباقات وأسعارها مثبّتة في هذا الكود، فكل
// تعديل على الموقع كان يترك الواتساب يعرض أسماء وأسعاراً قديمة. الآن تُبنى من
// «Fetch Site Catalog» (‎/api/requests?action=catalog) — نفس مصدر الموقع تماماً.
// إذا تعذّر الكتالوج تبقى القائمة تعمل بالأقسام والروابط الأساسية دون أسعار.
const SLUG = [
  ["company-formation", "تأسيس الشركات", "Company Formation", "🏢", "Company Formation"],
  ["foreign-investment", "الاستثمار الأجنبي", "Foreign Investment", "🌍", "Foreign Investment"],
  ["premium-residency", "الإقامة المميزة", "Premium Residency", "🪪", "Premium Residency"],
  ["government-relations", "العلاقات الحكومية", "Government Relations", "🏛️", "Government Relations"],
  ["hr-services", "الموارد البشرية", "HR Services", "👥", "HR Services"],
  ["recruitment", "التوظيف والاستقدام", "Recruitment & Talent", "🧑‍💼", "Recruitment"],
  ["business-support", "دعم الأعمال", "Business Support", "📊", "Business Support"],
  ["real-estate", "المكاتب ومساحات العمل", "Offices & Workspaces", "🏗️", "Real Estate"],
  ["ai-automation", "الأتمتة والذكاء الاصطناعي", "AI & Automation", "🤖", "AI Automation"]
];
const PKG_IC = {"starter-4":"🏪","silver":"🚀","gold":"📈","platinum":"🏗️","diamond":"👑","foreign-formation":"🌍","saudi-gulf-formation":"🏢","basic-legal":"📄","advanced":"⚖️","comprehensive":"🛡️","strategic":"♟️"};
const PKG_SH = {"starter-4":["المنشآت الصغيرة","Small establishment"],"silver":["الانطلاق","Launch"],"gold":["النمو","Growth"],"platinum":["التوسّع","Scale"],"diamond":["الشراكة المؤسسية","Enterprise"],"foreign-formation":["الشركات الأجنبية","Foreign companies"],"saudi-gulf-formation":["السعودية والخليجية","Saudi & Gulf"],"basic-legal":["الأساسية","Basic"],"advanced":["المتقدمة","Advanced"],"comprehensive":["الشاملة","Comprehensive"],"strategic":["الاستراتيجية","Strategic"]};
const GRP_META = {"management":["باقات الخدمات","Service packages","🗂️"],"formation":["باقات تأسيس الشركات","Company formation packages","🏢"],"legal":["الباقات القانونية","Legal packages","⚖️"]};
// حلول ومنصات الموقع — صفحات كاملة لا خدمات مفردة (الروابط من الكتالوج الحي).
const SOL_META = [
  ["worker-housing","🏠",["سكن العمالة","Worker housing"],["سكن مرخّص + إعاشة + نقل يومي لفرقك","Licensed housing + catering + daily transport"]],
  ["workspaces","🏢",["مكاتب ومساحات عمل","Offices & workspaces"],["مكتب خاص أو مشترك أو عنوان وطني معتمد","Private, shared or virtual office with national address"]],
  ["farina","🍽️",["التموين والضيافة","Corporate catering"],["وجبات وضيافة يومية لموظفيك","Daily meals and hospitality for your staff"]],
  ["business-development","📈",["تطوير الأعمال","Business development"],["فريق مبيعات وتطوير أعمال جاهز لك","A ready sales and business-development team"]],
  ["compliance-agent","🛡️",["مستشار الامتثال","Compliance advisor"],["تنبيه قبل أي مخالفة على كل المنصات","Alerts before any violation across platforms"]],
  ["ai-document-agent","📄",["مستشار المستندات","Document advisor"],["يقرأ ويراجع مستنداتك ويجهّز نماذجك","Reads, reviews and prepares your documents"]],
  ["task-force","⚡",["تاسك فورس","Task force"],["فريق تنفيذي مؤقت لمشروعك","A temporary execution team for your project"]],
  ["shared-services","🤝",["الخدمات المشتركة","Shared services"],["محاسبة وإدارة وتشغيل بفريق مشترك","Accounting, admin and ops via a shared team"]],
  ["account","🖥️",["بوابة العميل","Client portal"],["تابع طلباتك وافتح تذاكرك ومستنداتك","Track orders, open tickets, manage documents"]],
  ["calculator","🧮",["حاسبة التكاليف","Cost calculator"],["احسب تكلفة تأسيسك قبل ما تبدأ","Estimate your setup cost before you start"]]
];

let norm = {};
try { norm = $('Normalize WhatsApp Input').first().json || {}; } catch (e) { norm = $json || {}; }
let ctx = {};
try { ctx = $('Prepare AI Context').first().json || {}; } catch (e) { ctx = $json || {}; }

// الكتالوج الحي (قد يغيب إذا تعذّر الاتصال بالموقع — القائمة تبقى تعمل بدونه).
let CAT = {};
try { const c = $('Fetch Site Catalog').first().json; if (c && c.ok) CAT = c; } catch (e) { CAT = {}; }
const SERVICES = Array.isArray(CAT.services) ? CAT.services : [];
const PACKAGES = Array.isArray(CAT.packages) ? CAT.packages : [];
const PAGES = Array.isArray(CAT.pages) ? CAT.pages : [];

const to   = String(norm.phone || "").trim();
const id   = String(norm.interactive_id || "").trim();
const text = String(norm.normalized_text || norm.message_text || "").trim();
const greeting = norm.is_greeting_only === true;

// ---- language detection (mirror the customer, default Arabic) ----
const isEmailStr = (s) => /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(String(s || "").trim());
function detectLang(s) {
  s = String(s || "");
  if (/[؀-ۿ]/.test(s)) return "ar";
  if (/[A-Za-z]/.test(s) && !isEmailStr(s)) return "en";
  return "";
}
const clientName = String(norm.client_name || ctx.property_name || ctx.name || "").trim();
let lang = detectLang(norm.message_text || text) ||
           String(ctx.lang || ctx.property_language || "").toLowerCase() ||
           detectLang(clientName) || "ar";
