const L = (ar, en) => (lang === "en" ? en : ar);
const BASE = lang === "en" ? "https://businesspartner.sa" : "https://businesspartner.sa/ar";

const cut = (s, n) => { s = String(s || ""); return s.length > n ? s.slice(0, n - 1) + "…" : s; };
const catBySlug = (slug) => SLUG.find(c => c[0] === slug);
const catName = (c) => L(c[1], c[2]);
// خدمات القسم من الكتالوج الحي: المسعّرة أولاً ثم الباقي، بترتيب الكود.
function catServices(slug) {
  const c = catBySlug(slug); if (!c) return [];
  const rows = SERVICES.filter(s => s.category === c[4] || s.categoryAr === c[1]);
  const priced = rows.filter(s => s.priceLabel).sort((a, b) => String(a.code).localeCompare(String(b.code)));
  const rest = rows.filter(s => !s.priceLabel).sort((a, b) => String(a.code).localeCompare(String(b.code)));
  return priced.concat(rest);
}
const svcByCode = (code) => SERVICES.find(s => String(s.code).toUpperCase() === String(code).toUpperCase());
const svcName = (s) => L(s.nameAr || s.nameEn, s.nameEn || s.nameAr);
const svcUrl = (s) => (lang === "en" ? (s.urlEn || s.url) : (s.url || s.urlEn)) || (BASE + "/services");
const pkgByKey = (k) => PACKAGES.find(p => p.key === k);
const pkgsOfGroup = (g) => PACKAGES.filter(p => p.group === g);
const pkgSh = (p) => { const s = PKG_SH[p.key]; return s ? L(s[0], s[1]) : L(p.nameAr, p.nameEn); };
const pkgIc = (p) => PKG_IC[p.key] || "📦";
const pageByKey = (k) => PAGES.find(p => p.key === k);

// واتساب يرفض القائمة التفاعلية إذا تجاوز مجموع صفوفها عشرة (خطأ 131009)،
// ولا يرسل شيئاً — فيكتب العميل «مرحبا» ولا يصله رد. الحد يُفرض هنا مرة واحدة
// لكل القوائم: يُقصّ الفائض من أطول قسم مع إبقاء آخر صف فيه (صف التنقل).
const MAX_ROWS = 10;
function capRows(sections) {
  const secs = (sections || []).map(s => ({ title: s.title, rows: (s.rows || []).slice() }));
  let total = secs.reduce((n, s) => n + s.rows.length, 0);
  while (total > MAX_ROWS) {
    let big = 0;
    for (let i = 1; i < secs.length; i++) if (secs[i].rows.length > secs[big].rows.length) big = i;
    if (secs[big].rows.length <= 1) break;
    secs[big].rows.splice(secs[big].rows.length - 2, 1);
    total--;
  }
  return secs.filter(s => s.rows.length);
}
function listMsg(header, bodyText, footer, button, sections) {
  const safeSections = capRows(sections).map(sec => ({
    title: cut(sec.title, 24),
    rows: (sec.rows || []).map(r => ({ id: cut(r.id, 200), title: cut(r.title, 24), description: cut(r.description, 72) }))
  }));
  return JSON.stringify({
    messaging_product: "whatsapp", recipient_type: "individual", to,
    type: "interactive",
    interactive: { type: "list",
      header: { type: "text", text: cut(header, 60) },
      body:   { text: cut(bodyText, 1024) },
      footer: { text: cut(footer, 60) },
      action: { button: cut(button, 20), sections: safeSections } }
  });
}
function textMsg(t) {
  return JSON.stringify({ messaging_product: "whatsapp", recipient_type: "individual", to,
    type: "text", text: { preview_url: true, body: cut(t, 4000) } });
}

