const pad2 = (n) => String(n).padStart(2, "0");
function riyadhNow() { return new Date(Date.now() + 3 * 3600 * 1000); }

function dayPicker() {
  const base = riyadhNow(); const rows = [];
  const DAYS = lang === "en" ? EN_DAYS : AR_DAYS;
  const MONTHS = lang === "en" ? EN_MONTHS : AR_MONTHS;
  for (let i = 1; i <= 14 && rows.length < 9; i++) {
    const d = new Date(base.getTime() + i * 86400000);
    if (d.getUTCDay() === 5) continue;
    const iso = d.getUTCFullYear() + "-" + pad2(d.getUTCMonth() + 1) + "-" + pad2(d.getUTCDate());
    rows.push({ id: "bkday_" + iso, title: cut(DAYS[d.getUTCDay()] + " " + d.getUTCDate() + " " + MONTHS[d.getUTCMonth()], 24), description: L("اضغط لعرض الأوقات المتاحة", "Tap to see available times") });
  }
  return listMsg(L("🗓️ استشارة مجانية للشركات", "🗓️ Free consultation (companies)"),
    L("هذه الاستشارة مخصّصة للشركات وأصحاب الأعمال 🏢\nاختر اليوم المناسب 👇 (كل الأيام متاحة ما عدا الجمعة، والأوقات حسب توفّر مستشارنا).",
      "This consultation is for companies and business owners 🏢\nPick a suitable day 👇 (all days except Friday; times depend on our advisor's availability)."),
    L("بيزنس بارتنر", "Business Partner"), L("اختر اليوم", "Choose day"), [{ title: L("الأيام المتاحة", "Available days"), rows }]);
}

