// Input: the day's events from "Get Day Events" (Google Calendar). Emits a
// WhatsApp time-slot list (9:00–17:30 starts, 30-min appts) showing ONLY the
// slots that don't overlap an existing calendar event.
const norm = $('Normalize WhatsApp Input').first().json || {};
const to = String(norm.phone || '').trim();
const id = String(norm.interactive_id || '').trim();
const date = id.slice(6); // bkday_YYYY-MM-DD
const pad2 = (n) => String(n).padStart(2, '0');
const AR_DAYS = ["الأحد","الإثنين","الثلاثاء","الأربعاء","الخميس","الجمعة","السبت"];
const AR_MONTHS = ["يناير","فبراير","مارس","أبريل","مايو","يونيو","يوليو","أغسطس","سبتمبر","أكتوبر","نوفمبر","ديسمبر"];
const cut = (s, n) => { s = String(s || ''); return s.length > n ? s.slice(0, n - 1) + '…' : s; };
function humanDate(iso) { const p = String(iso).split('-').map(Number); if (p.length !== 3) return iso; const d = new Date(Date.UTC(p[0], p[1]-1, p[2])); return AR_DAYS[d.getUTCDay()] + ' ' + p[2] + ' ' + AR_MONTHS[p[1]-1]; }
function listMsg(header, body, footer, button, rows) {
  return JSON.stringify({ messaging_product: 'whatsapp', recipient_type: 'individual', to, type: 'interactive',
    interactive: { type: 'list', header: { type: 'text', text: cut(header, 60) }, body: { text: cut(body, 1024) }, footer: { text: cut(footer, 60) },
      action: { button: cut(button, 20), sections: [{ title: cut('الأوقات المتاحة', 24), rows: rows.map(r => ({ id: cut(r.id, 200), title: cut(r.title, 24), description: cut(r.description, 72) })) }] } } });
}
function textMsg(t) { return JSON.stringify({ messaging_product: 'whatsapp', recipient_type: 'individual', to, type: 'text', text: { preview_url: false, body: cut(t, 4000) } }); }

// Collect busy intervals (minutes from midnight, Riyadh local) for THIS date.
const minFromDT = (dtStr) => { const t = String(dtStr).split('T')[1] || ''; return (+t.slice(0, 2)) * 60 + (+t.slice(3, 5)); };
const busy = [];
for (const it of items) {
  const e = it.json || {};
  if (!e.start) continue; // skip non-event passthrough
  if (e.start.date && !e.start.dateTime) { busy.push([0, 1440]); continue; } // all-day → whole day busy
  if (e.start.dateTime && e.end && e.end.dateTime) {
    const sd = String(e.start.dateTime).slice(0, 10), ed = String(e.end.dateTime).slice(0, 10);
    const s = (sd === date) ? minFromDT(e.start.dateTime) : 0;
    const en = (ed === date) ? minFromDT(e.end.dateTime) : 1440;
    busy.push([s, en]);
  }
}

const rows = [];
for (let h = 9; h <= 17; h++) { // 9:00 .. 17:00 starts (30-min, ends by 17:30/18:00)
  const s = h * 60, e = s + 30;
  const overlap = busy.some(b => s < b[1] && e > b[0]);
  if (!overlap) {
    const label = h < 12 ? (h + ':00 ص') : (h === 12 ? '12:00 م' : ((h - 12) + ':00 م'));
    rows.push({ id: 'bktime_' + date + '_' + pad2(h) + ':00', title: label, description: 'موعد 30 دقيقة عبر Google Meet' });
  }
}

let body;
if (rows.length === 0) {
  body = textMsg('عذراً 😔 يوم ' + humanDate(date) + ' محجوز بالكامل عند مستشارنا.\nاختر يوماً آخر — اكتب «احجز» من جديد أو «قائمة».');
