const JOURNEY = L(
  '\n\nجاوبني بأي تفصيل عندك، وأنا أجهّز لك:\n📝 *نطاق العمل* المكتوب — تراجعه وتعدّله\n💰 *عرض السعر* بأتعاب واضحة\n📜 *العقد* بعد موافقتك\n🧾 *الفاتورة* و💳 *رابط الدفع*\n\nما فيه رسوم قبل ما توافق على العرض ✋',
  '\n\nReply with whatever detail you have and I will prepare:\n📝 A written *scope of work* for you to review and edit\n💰 A *quote* with clear fees\n📜 The *contract* once you approve\n🧾 The *invoice* and 💳 a *payment link*\n\nNothing is charged before you approve the quote ✋'
);

let body = j.menu_body || null;
let kind = j.menu_kind || 'none';

if (DOORS[id]) {
  body = textMsg(DOORS[id][lang] + JOURNEY);
  kind = 'journey_' + id.slice(6);
} else if (id === 'my_orders') {
  body = textMsg(L(
    '📄 *طلباتك وعروضك في مكان واحد*\n\nمن بوابتك تشوف نطاق العمل، وعرض السعر، والعقد، والفاتورة، وحالة كل طلب لحظة بلحظة:\n' + BASE + '/account\n\nوإذا تبيني أتابع لك طلباً معيناً، أرسل لي رقمه (مثال: BP-123456) وأجيب لك حالته الآن 👇',
    '📄 *All your orders and quotes in one place*\n\nYour portal shows the scope, quote, contract, invoice and live status of every order:\n' + BASE + '/account\n\nOr send me an order number (e.g. BP-123456) and I will pull its status right now 👇'
  ));
  kind = 'my_orders';
} else if (id === 'pay_now') {
  body = textMsg(L(
    '💳 *دفع فاتورة*\n\nأرسل لي *رقم الطلب أو الفاتورة* (مثال: BP-123456) وأرجع لك برابط دفع آمن فوراً.\n\nوسائل الدفع: مدى · فيزا · ماستركارد · أبل باي · تقسيط بدون فوائد.\nوتقدر تدفع أيضاً من بوابتك مباشرة:\n' + BASE + '/account',
    '💳 *Pay an invoice*\n\nSend me the *order or invoice number* (e.g. BP-123456) and I will reply with a secure payment link.\n\nWe accept Mada · Visa · Mastercard · Apple Pay · interest-free instalments.\nYou can also pay straight from your portal:\n' + BASE + '/account'
  ));
  kind = 'pay_now';
} else if (kind === 'main' && id !== 'main_menu') {
  // التحية و«القائمة» و«رجوع» تفتح الأبواب الثلاثة؛ صف main_menu وحده
  // يُبقي قائمة الأقسام القديمة كما هي.
  body = journeyMenu();
  kind = 'main_journey';
}

return [{ json: { ...j, menu_kind: kind, has_menu: body !== null, menu_body: body } }];
